import kotlin.test.*

@Suppress("EXTENSION_SHADOWED_BY_MEMBER")
private fun <K, V> Map<K, V>.getOrDefault(key: K, defaultValue: V): V {
    @Suppress("UNCHECKED_CAST")
    return if (containsKey(key)) get(key) as V else defaultValue
}

private class HangError : Error()

private object Probe {
    var steps = 0
    val kinds = mutableSetOf<String>()
    fun reset() {
        steps = 0
        kinds.clear()
    }
}

// injected after every `while (...) {`; deterministic hang detection, no threads (JVM and Native)
private fun tick() {
    if (++Probe.steps > 1_000_000) throw HangError()
}

private fun case(f: () -> Unit) {
    Probe.steps = 0
    try {
        f()
    } catch (e: AssertionError) {
        Probe.kinds += "wrong"
    } catch (e: HangError) {
        Probe.kinds += "hang"
    } catch (e: Throwable) {
        Probe.kinds += "crash"
    }
}

private fun pw(b: Int, e: Int): Int {
    var r = 1
    repeat(e) { r *= b }
    return r
}

object V { // reference (control)
    fun sumAndMax(nums: IntArray): Pair<Int, Int> {
        // сумма всех чисел
        var sum = 0
        // текущий максимум
        var max = nums[0]
        // один проход по массиву
        for (num in nums) {
            sum += num
            // новый максимум
            if (num > max) max = num
        }
        // пара (сумма, максимум)
        return sum to max
    }

    fun run() {
        case { assertEquals(6 to 3, sumAndMax(intArrayOf(1, 2, 3))) }
        case { assertEquals(-7 to -2, sumAndMax(intArrayOf(-5, -2))) }
        case { assertEquals(7 to 7, sumAndMax(intArrayOf(7))) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: stdlib sum()/max(), а не ручной проход; все массивы длины 1..5 из {-3, -1, 0, 2}
        val vals = intArrayOf(-3, -1, 0, 2)
        for (n in 1..5) case {
            for (m in 0 until pw(4, n)) {
                val a = IntArray(n) { vals[(m / pw(4, it)) % 4] }
                assertEquals(a.sum() to a.max(), sumAndMax(a))
            }
        }
        case { assertEquals(0 to 0, sumAndMax(intArrayOf(0))) }
        case { assertEquals(Int.MAX_VALUE to Int.MAX_VALUE, sumAndMax(intArrayOf(Int.MAX_VALUE))) }
        case { assertEquals(Int.MIN_VALUE to Int.MIN_VALUE, sumAndMax(intArrayOf(Int.MIN_VALUE))) }
        case { assertEquals(-1 to Int.MAX_VALUE, sumAndMax(intArrayOf(Int.MIN_VALUE, Int.MAX_VALUE))) }
        case { assertEquals(9 to 5, sumAndMax(intArrayOf(5, 1, 3))) } // максимум первым
        case { assertEquals(9 to 5, sumAndMax(intArrayOf(1, 3, 5))) } // максимум последним
        // контрпримеры из причин
        case { assertEquals(3 to 2, sumAndMax(intArrayOf(1, 2))) }
        case { assertEquals(4 to 3, sumAndMax(intArrayOf(3, 1))) }
        case { assertEquals(1 to 1, sumAndMax(intArrayOf(1))) }
    }

    fun kinds(): String {
        Probe.reset()
        run()
        return Probe.kinds.sorted().joinToString(",")
    }
}

